insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e75d4342-af1d-5273-ad6a-ab643d8bf54e', 'short', 'Explain why a sprinter''s muscles produce lactate in a 100 m race but not during a slow walk.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e75d4342-af1d-5273-ad6a-ab643d8bf54e', 'During sprinting, oxygen cannot be supplied to the muscles fast enough for aerobic respiration alone [1]; so muscles also respire anaerobically, producing lactate [1]; this releases ATP quickly without oxygen, although the yield per glucose is low [1]. During walking, oxygen supply meets demand, so respiration is aerobic.', 'During sprinting, oxygen cannot be supplied to the muscles fast enough for aerobic respiration alone [1]; so muscles also respire anaerobically, producing lactate [1]; this releases ATP quickly without oxygen, although the yield per glucose is low [1]. During walking, oxygen supply meets demand, so respiration is aerobic.', '[{"text": "Marking point 1", "any": ["insufficient oxygen", "not enough oxygen", "oxygen cannot", "lack of oxygen", "oxygen supply"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["anaerobic"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["fast", "quickly", "rapid", "extra atp", "more atp"], "all": [], "marks": 1}]'::jsonb, 'During sprinting, oxygen cannot be supplied to the muscles fast enough for aerobic respiration alone [1]; so muscles also respire anaerobically, producing lactate [1]; this releases ATP quickly without oxygen, although the yield per glucose is low [1]. During walking, oxygen supply meets demand, so respiration is aerobic.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('3d924cfc-ff0c-5c19-826f-52f60411cfe5', 'e75d4342-af1d-5273-ad6a-ab643d8bf54e', 29);
