insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1792a300-6530-5c0d-81db-a04018978709', 'Thick waxy cuticle reduces evaporation from the surface [1]; fewer or sunken stomata / hairs / rolled leaves trap humid air and reduce the water vapour gradient [1].', 'Thick waxy cuticle reduces evaporation from the surface [1]; fewer or sunken stomata / hairs / rolled leaves trap humid air and reduce the water vapour gradient [1].', '[{"text": "Marking point 1", "any": ["cuticle", "wax"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["fewer stomata", "sunken", "hairs", "rolled", "small leaves", "spines"], "all": [], "marks": 1}]'::jsonb, 'Thick waxy cuticle reduces evaporation from the surface [1]; fewer or sunken stomata / hairs / rolled leaves trap humid air and reduce the water vapour gradient [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
