insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a3eb8f28-9e2d-5ad1-aca1-d2c3e2085cea', 'short', 'Explain the S-shape of the oxygen dissociation curve of haemoglobin.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oxygen-Haemoglobin_dissociation_curves.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a3eb8f28-9e2d-5ad1-aca1-d2c3e2085cea', 'At low pO₂ the first O₂ binds with difficulty, so the curve starts shallow [1]; binding changes the shape of haemoglobin, so further O₂ binds more easily (cooperative binding), giving the steep middle [1]; at high pO₂ all four haem groups are occupied, so the curve levels off [1].', 'At low pO₂ the first O₂ binds with difficulty, so the curve starts shallow [1]; binding changes the shape of haemoglobin, so further O₂ binds more easily (cooperative binding), giving the steep middle [1]; at high pO₂ all four haem groups are occupied, so the curve levels off [1].', '[{"text": "Marking point 1", "any": ["first oxygen", "low affinity at low", "hard to bind"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["shape change", "cooperative", "conformation", "easier"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["plateau", "saturated", "all sites", "four"], "all": [], "marks": 1}]'::jsonb, 'At low pO₂ the first O₂ binds with difficulty, so the curve starts shallow [1]; binding changes the shape of haemoglobin, so further O₂ binds more easily (cooperative binding), giving the steep middle [1]; at high pO₂ all four haem groups are occupied, so the curve levels off [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('6ada932e-33a7-5830-9fbf-fe505e0541a7', 'a3eb8f28-9e2d-5ad1-aca1-d2c3e2085cea', 22);
