insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e4df402e-91cf-54a4-bc93-bfec0b62d7bb', 'At the low pO₂ in the placenta, foetal haemoglobin is more saturated than maternal haemoglobin [1]; so oxygen is transferred from the mother''s blood to the foetus''s blood [1].', 'At the low pO₂ in the placenta, foetal haemoglobin is more saturated than maternal haemoglobin [1]; so oxygen is transferred from the mother''s blood to the foetus''s blood [1].', '[{"text": "Marking point 1", "any": ["more saturated", "higher saturation", "binds more", "takes oxygen", "same partial pressure"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["mother", "maternal", "placenta"], "all": [], "marks": 1}]'::jsonb, 'At the low pO₂ in the placenta, foetal haemoglobin is more saturated than maternal haemoglobin [1]; so oxygen is transferred from the mother''s blood to the foetus''s blood [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
