insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('14867f66-3a79-5fca-8521-6ba89ceeef15', 1, 'Proteins: plasma. Glucose and ions: both. Bathes cells and formed by filtration: tissue fluid.', 'Tissue fluid') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
