insert into public.questions (id, kind, prompt, options, marks, image_url) values ('01b00391-006c-5162-bd6c-48db719ab5b0', 'short', 'Explain how tissue fluid is formed and returned to the blood.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('01b00391-006c-5162-bd6c-48db719ab5b0', 'At the arteriole end, high blood pressure forces plasma out of the capillary (pressure filtration) [1]; at the venule end, pressure is lower so tissue fluid drains back into the capillary [1]; excess fluid drains into lymph ducts and returns to the blood [1].', 'At the arteriole end, high blood pressure forces plasma out of the capillary (pressure filtration) [1]; at the venule end, pressure is lower so tissue fluid drains back into the capillary [1]; excess fluid drains into lymph ducts and returns to the blood [1].', '[{"text": "Marking point 1", "any": ["high pressure", "arteriole", "pressure filtration"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["low pressure", "venule", "back into"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["lymph"], "all": [], "marks": 1}]'::jsonb, 'At the arteriole end, high blood pressure forces plasma out of the capillary (pressure filtration) [1]; at the venule end, pressure is lower so tissue fluid drains back into the capillary [1]; excess fluid drains into lymph ducts and returns to the blood [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('10deb32e-b1f9-5a4b-9e9c-75f26ba19860', '01b00391-006c-5162-bd6c-48db719ab5b0', 17);
