insert into public.questions (id, kind, prompt, options, marks, image_url) values ('b408e14a-4b0f-5a1c-acbf-15dd8c85b819', 'short', 'Outline the events in the left side of the heart during one cardiac cycle.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b408e14a-4b0f-5a1c-acbf-15dd8c85b819', 'The SA node starts the beat [1]; the atrium contracts, pushing blood through the open AV valve into the ventricle [1]; the ventricle contracts, pressure rises and the AV valve closes [1]; the semilunar valve opens and blood is pumped into the aorta; then the ventricle relaxes and the semilunar valve closes [1].', 'The SA node starts the beat [1]; the atrium contracts, pushing blood through the open AV valve into the ventricle [1]; the ventricle contracts, pressure rises and the AV valve closes [1]; the semilunar valve opens and blood is pumped into the aorta; then the ventricle relaxes and the semilunar valve closes [1].', '[{"text": "Marking point 1", "any": ["sinoatrial", "sa node", "pacemaker"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["atrial systole", "atrium contracts"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["atrioventricular valve closes"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["aorta", "semilunar valve opens"], "all": [], "marks": 1}]'::jsonb, 'The SA node starts the beat [1]; the atrium contracts, pushing blood through the open AV valve into the ventricle [1]; the ventricle contracts, pressure rises and the AV valve closes [1]; the semilunar valve opens and blood is pumped into the aorta; then the ventricle relaxes and the semilunar valve closes [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('10deb32e-b1f9-5a4b-9e9c-75f26ba19860', 'b408e14a-4b0f-5a1c-acbf-15dd8c85b819', 22);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8a679b97-c54c-550d-bc74-509a9d609e0a', 'short', 'Explain why the wall of the left ventricle is thicker than that of the right ventricle.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('8a679b97-c54c-550d-bc74-509a9d609e0a', 'The left ventricle pumps blood to the whole body, the right only to the lungs [1]; so it must generate a much higher pressure, needing more cardiac muscle [1].', 'The left ventricle pumps blood to the whole body, the right only to the lungs [1]; so it must generate a much higher pressure, needing more cardiac muscle [1].', '[{"text": "Marking point 1", "any": ["body", "whole body", "systemic", "aorta"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["pressure", "further", "greater distance", "more force"], "all": [], "marks": 1}]'::jsonb, 'The left ventricle pumps blood to the whole body, the right only to the lungs [1]; so it must generate a much higher pressure, needing more cardiac muscle [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
